inline std::string_view manualMarketPanelMessageKeyName(ManualMarketPanelMessageKey key){
    static constexpr std::array<std::string_view,manualMarketPanelMessageKeyCount> names={{"manual_market.panel.short_title","manual_market.panel.short_resize","manual_market.panel.short_keys","manual_market.panel.footer_edit","manual_market.panel.footer_review","manual_market.panel.footer_browse","manual_market.panel.local_defaults","manual_market.panel.title","manual_market.panel.unsaved_suffix","manual_market.panel.decimal_guide","manual_market.panel.validity_guide","manual_market.panel.skew_guide","manual_market.panel.reference_guide","manual_market.panel.editor_keys","manual_market.panel.leave_title","manual_market.panel.leave_keys","manual_market.panel.review_heading","manual_market.panel.no_changes","manual_market.panel.activation_live","manual_market.panel.activation_next","manual_market.panel.cli_wins","manual_market.panel.no_finance","manual_market.panel.local_only","manual_market.panel.identity","manual_market.panel.current_off","manual_market.panel.no_session","manual_market.panel.configured_boundary","manual_market.panel.no_provider"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage manualMarketPanelMessage(std::string_view language,ManualMarketPanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=manualMarketPanelMessageKeyCount)return {};
    const auto &source=manualMarketPanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:manualMarketPanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string manualMarketPanelEnglish(ManualMarketPanelMessageKey key){return std::string(manualMarketPanelMessage("en",key).text);}
